secoes.formula:
valor_total = (DE4 × interchange_rate) + unit_fee
if valor_total < min_fee_limit → valor_total = min_fee_limit
if valor_total > max_fee_limit → valor_total = max_fee_limit  // CAP
if fee_direction = 'ISS'/'DR' → CUSTO para o Adquirente (débito)
if fee_direction = 'ACQ'/'CR' → RECEITA para o Adquirente (crédito)
